/* @lc app=leetcode id=2617 lang=kotlin */ class Solution { fun find(a: IntArray, x: Int): Int = generateSequence(x) { if (a[it] == it) null else a[it] }.toList().let { p -> p.last().also { r -> p.forEach { a[it] = r } } } fun vis(rn: Array<IntArray>, cn: Array<IntArray>, i: Int, j: Int) = rn[i].set(j, j + 1).also { cn[j][i] = i + 1 } fun minimumVisitedCells(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> Array(m) { IntArray(n + 1) { it } }.let { rn -> Array(n) { IntArray(m + 1) { it } }.let { cn -> vis(rn, cn, 0, 0).let { generateSequence(listOf(0 to 0) to 1) { (f, d) -> f.flatMap { (i, j) -> grid[i][j].let { g -> generateSequence(find(rn[i], j + 1)) { find(rn[i], it + 1) }.takeWhile { it <= minOf(n - 1, j + g) }.map { k -> vis(rn, cn, i, k).let { i to k } }.toList() + generateSequence(find(cn[j], i + 1)) { find(cn[j], it + 1) }.takeWhile { it <= minOf(m - 1, i + g) }.map { k -> vis(rn, cn, k, j).let { k to j } }.toList() } }.takeIf { it.isNotEmpty() }?.let { it to d + 1 } }.firstOrNull { (f, _) -> (m - 1 to n - 1) in f }?.second ?: -1 } } } } } }